/** Explicit one-record-at-a-time clinical review, offline preview, and user-triggered transmission. */
public final class SatuSehatKirimNutritionOrder extends JDialog {
    private static final Color INK=new Color(24,44,62),TEAL=new Color(12,132,124),MUTED=new Color(100,116,139),BACK=new Color(243,247,250);
    private final JDateChooser from=calendar(LocalDate.now(SatuSehatNutritionOrderPayload.ZONE).withDayOfMonth(1)),to=calendar(LocalDate.now(SatuSehatNutritionOrderPayload.ZONE));
    private final JTextField filter=new JTextField(20);
    private final JButton search=SatuSehatAturNutritionOrder.actionButton("Cari ADIME",true),edit=SatuSehatAturNutritionOrder.actionButton("Lengkapi instruksi",false),preview=SatuSehatAturNutritionOrder.actionButton("Pratinjau offline",false),send=SatuSehatAturNutritionOrder.actionButton("Kirim Baru",true),update=SatuSehatAturNutritionOrder.actionButton("Update",false),recover=SatuSehatAturNutritionOrder.actionButton("Rekonsiliasi ID",false),close=SatuSehatAturNutritionOrder.actionButton("Tutup",false);
    private final JLabel count=new JLabel("0 catatan"),selection=new JLabel("Pilih satu catatan untuk melengkapi instruksi atau melakukan pengiriman.");
    private final JLabel info=new JLabel("Sumber: ADIME tersimpan. Catatan lama perlu ditinjau; tidak otomatis menjadi instruksi aktif.");
    private final DefaultTableModel model=new DefaultTableModel(new String[]{"No. Rawat","RM","Pasien","Tanggal ADIME","Petugas ADIME","Intervensi","Instruksi Sumber","Status Kelengkapan","ID Encounter","ID NutritionOrder"},0){@Override public boolean isCellEditable(int r,int c){return false;}};
    private final JTable table=new JTable(model);
    private final SatuSehatNutritionOrderService service=new SatuSehatNutritionOrderService();
    private List<SatuSehatNutritionOrderService.Row> rows=new ArrayList<SatuSehatNutritionOrderService.Row>();
    public SatuSehatKirimNutritionOrder(Window owner,boolean modal){
        super(owner,"Kirim NutritionOrder - Instruksi Diet SATUSEHAT",modal?ModalityType.APPLICATION_MODAL:ModalityType.MODELESS);
        setDefaultCloseOperation(DISPOSE_ON_CLOSE);JPanel root=new JPanel(new BorderLayout(0,14));root.setBackground(BACK);root.setBorder(BorderFactory.createEmptyBorder(18,20,16,20));setContentPane(root);
        JPanel top=new JPanel(new BorderLayout(0,12));top.setOpaque(false);JPanel banner=new SatuSehatAturNutritionOrder.Surface(new BorderLayout(),INK);banner.setBorder(BorderFactory.createEmptyBorder(16,20,16,20));
        JPanel titleBox=new JPanel(new GridLayout(2,1,0,5));titleBox.setOpaque(false);JLabel title=new JLabel("Pengiriman instruksi diet");title.setFont(new Font("Segoe UI",Font.BOLD,23));title.setForeground(Color.WHITE);titleBox.add(title);JLabel subtitle=new JLabel("Tinjau catatan ADIME, lengkapi instruksi, lalu kirim NutritionOrder.");subtitle.setFont(new Font("Segoe UI",Font.PLAIN,13));subtitle.setForeground(new Color(194,218,228));titleBox.add(subtitle);banner.add(titleBox,BorderLayout.CENTER);JLabel badge=new JLabel("SATUSEHAT  /  GIZI");badge.setForeground(new Color(111,226,211));badge.setFont(new Font("Segoe UI",Font.BOLD,12));banner.add(badge,BorderLayout.EAST);top.add(banner,BorderLayout.NORTH);
        JPanel filters=new SatuSehatAturNutritionOrder.Surface(new GridBagLayout(),Color.WHITE);filters.setBorder(BorderFactory.createEmptyBorder(12,16,12,16));GridBagConstraints fc=new GridBagConstraints();fc.insets=new Insets(0,0,0,14);fc.fill=GridBagConstraints.HORIZONTAL;fc.gridx=0;filters.add(filterField("Tanggal ADIME · dari",from),fc);fc.gridx=1;filters.add(filterField("Sampai tanggal",to),fc);fc.gridx=2;fc.weightx=1;filter.setFont(new Font("Segoe UI",Font.PLAIN,14));filter.setPreferredSize(new Dimension(220,36));filter.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(new Color(213,225,231)),BorderFactory.createEmptyBorder(6,10,6,10)));filters.add(filterField("Cari nomor rawat, RM, atau nama",filter),fc);fc.gridx=3;fc.weightx=0;fc.insets=new Insets(20,0,0,0);filters.add(search,fc);top.add(filters,BorderLayout.CENTER);root.add(top,BorderLayout.NORTH);
        JPanel records=new SatuSehatAturNutritionOrder.Surface(new BorderLayout(0,10),Color.WHITE);records.setBorder(BorderFactory.createEmptyBorder(12,14,12,14));JPanel tableTitle=new JPanel(new BorderLayout());tableTitle.setOpaque(false);JLabel recordsLabel=new JLabel("Catatan ADIME Gizi");recordsLabel.setForeground(INK);recordsLabel.setFont(new Font("Segoe UI",Font.BOLD,15));count.setFont(new Font("Segoe UI",Font.BOLD,13));count.setForeground(TEAL);tableTitle.add(recordsLabel,BorderLayout.WEST);tableTitle.add(count,BorderLayout.EAST);records.add(tableTitle,BorderLayout.NORTH);
        table.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);table.setAutoResizeMode(JTable.AUTO_RESIZE_OFF);int[] widths={175,85,220,175,160,320,320,300,260,260};for(int i=0;i<model.getColumnCount();i++)table.getColumnModel().getColumn(i).setPreferredWidth(widths[i]);table.moveColumn(7,4);
        table.setRowHeight(36);table.setFont(new Font("Segoe UI",Font.PLAIN,13));table.setShowGrid(false);table.setIntercellSpacing(new Dimension(0,0));table.setFillsViewportHeight(true);table.setBackground(Color.WHITE);table.getTableHeader().setReorderingAllowed(false);table.getTableHeader().setFont(new Font("Segoe UI",Font.BOLD,12));table.getTableHeader().setBackground(new Color(234,243,247));table.getTableHeader().setPreferredSize(new Dimension(100,36));
        table.setDefaultRenderer(Object.class,new DefaultTableCellRenderer(){@Override public Component getTableCellRendererComponent(JTable t,Object v,boolean selected,boolean focused,int row,int column){super.getTableCellRendererComponent(t,v,selected,focused,row,column);setBorder(BorderFactory.createEmptyBorder(0,10,0,10));setBackground(selected?new Color(214,239,235):row%2==0?Color.WHITE:new Color(247,250,252));setForeground(INK);setFont(new Font("Segoe UI",Font.PLAIN,13));if(t.convertColumnIndexToModel(column)==7){setFont(getFont().deriveFont(Font.BOLD));String status=java.util.Objects.toString(v,"");setForeground(status.startsWith("Sudah terkirim")?TEAL:status.startsWith("Siap")?new Color(29,111,165):new Color(151,100,32));}setToolTipText(java.util.Objects.toString(v,""));return this;}});
        JScrollPane tableScroll=new JScrollPane(table);tableScroll.setBorder(BorderFactory.createLineBorder(new Color(225,234,239)));tableScroll.getViewport().setBackground(Color.WHITE);records.add(tableScroll,BorderLayout.CENTER);selection.setFont(new Font("Segoe UI",Font.PLAIN,12));selection.setForeground(MUTED);records.add(selection,BorderLayout.SOUTH);root.add(records,BorderLayout.CENTER);
        table.getSelectionModel().addListSelectionListener(e->{int row=table.getSelectedRow();selection.setText(row<0?"Pilih satu catatan untuk melengkapi instruksi atau melakukan pengiriman.":"Dipilih: "+model.getValueAt(row,1)+"  ·  "+model.getValueAt(row,2)+"  |  "+model.getValueAt(row,0));});
        JPanel bottom=new SatuSehatAturNutritionOrder.Surface(new BorderLayout(0,10),Color.WHITE);bottom.setBorder(BorderFactory.createEmptyBorder(12,14,12,14));JPanel buttons=new JPanel(new BorderLayout());buttons.setOpaque(false);JPanel reviewButtons=new JPanel(new FlowLayout(FlowLayout.LEFT,6,0)),sendButtons=new JPanel(new FlowLayout(FlowLayout.RIGHT,6,0));reviewButtons.setOpaque(false);sendButtons.setOpaque(false);reviewButtons.add(edit);reviewButtons.add(preview);for(JButton b:new JButton[]{send,update,recover,close})sendButtons.add(b);buttons.add(reviewButtons,BorderLayout.WEST);buttons.add(sendButtons,BorderLayout.EAST);bottom.add(buttons,BorderLayout.NORTH);info.setFont(new Font("Segoe UI",Font.PLAIN,12));info.setForeground(MUTED);bottom.add(info,BorderLayout.SOUTH);root.add(bottom,BorderLayout.SOUTH);
        preview.setToolTipText("Pratinjau offline menggunakan ID contoh; tidak memanggil API.");
        search.addActionListener(e->load());filter.addActionListener(e->load());edit.addActionListener(e->edit());preview.addActionListener(e->preview());send.addActionListener(e->send(false));update.addActionListener(e->send(true));recover.addActionListener(e->recover());close.addActionListener(e->dispose());
        Dimension screen=Toolkit.getDefaultToolkit().getScreenSize();setSize(Math.min(1350,screen.width-50),Math.min(720,screen.height-90));setLocationRelativeTo(owner);busy(false);
    }
    private static JPanel filterField(String text,JComponent field){JPanel p=new JPanel(new BorderLayout(0,7));p.setOpaque(false);JLabel label=new JLabel(text);label.setFont(new Font("Segoe UI",Font.PLAIN,12));label.setForeground(MUTED);p.add(label,BorderLayout.NORTH);p.add(field,BorderLayout.CENTER);return p;}
    public static JDateChooser calendar(LocalDate date){JDateChooser c=new JDateChooser();c.setLocale(new Locale("id","ID"));c.setDateFormatString("dd MMM yyyy");c.setFont(new Font("Segoe UI",Font.PLAIN,13));c.setPreferredSize(new Dimension(175,36));if(c.getDateEditor().getUiComponent() instanceof JTextField)((JTextField)c.getDateEditor().getUiComponent()).setEditable(false);setDateValue(c,date);return c;}
    public static void setDateValue(JDateChooser picker,LocalDate day){Calendar c=Calendar.getInstance();c.clear();c.set(day.getYear(),day.getMonthValue()-1,day.getDayOfMonth(),12,0,0);picker.setCalendar(c);}
    public static String dateValue(JDateChooser picker){Calendar c=picker.getCalendar();if(c==null)throw new IllegalArgumentException("Pilih tanggal awal dan akhir pada kalender.");return LocalDate.of(c.get(Calendar.YEAR),c.get(Calendar.MONTH)+1,c.get(Calendar.DAY_OF_MONTH)).toString();}
    public void openSource(String visit,String date){setDateValue(from,LocalDate.parse(date.substring(0,10)));setDateValue(to,LocalDate.parse(date.substring(0,10)));filter.setText(visit);load();}
    public void load(){try{String a=dateValue(from),b=dateValue(to),q=filter.getText().trim();work(()->service.load(a,b,q),result->{rows=result;refresh();info.setText(result.size()+" catatan. Lengkapi dan simpan tinjauan sebelum pengiriman.");});}catch(Exception e){showError(e);}}
    private void refresh(){model.setRowCount(0);for(SatuSehatNutritionOrderService.Row r:rows)model.addRow(new Object[]{r.visit,r.rm,r.name,r.date.replaceAll("\\.0$",""),r.author,r.intervention,r.instruction,service.readiness(r),r.encounter,r.remote});count.setText(rows.size()+" catatan");}
    private SatuSehatNutritionOrderService.Row selected(){int n=table.getSelectedRow();if(n<0){JOptionPane.showMessageDialog(this,"Pilih satu catatan ADIME.");return null;}return rows.get(n);}
    private void edit(){final SatuSehatNutritionOrderService.Row r=selected();if(r==null)return;if(!SatuSehatNutritionOrderService.canEdit()){JOptionPane.showMessageDialog(this,"Memerlukan akses Catatan ADIME Gizi.");return;}
        work(()->new Object[]{service.doctors(),service.doctorCandidates(r.visit)},data->{
            @SuppressWarnings("unchecked") List<SatuSehatNutritionOrderService.Doctor> doctors=(List<SatuSehatNutritionOrderService.Doctor>)data[0];
            @SuppressWarnings("unchecked") List<String> candidates=(List<String>)data[1];
            SatuSehatAturNutritionOrder dialog=new SatuSehatAturNutritionOrder(this,r,doctors,candidates);dialog.setVisible(true);ObjectNode review=dialog.result();if(review!=null)work(()->{service.save(r,review);return true;},ok->{refresh();info.setText("Tinjauan tersimpan lokal. Belum dikirim ke SATUSEHAT.");});
        });
    }
    private void preview(){SatuSehatNutritionOrderService.Row r=selected();if(r==null)return;try{JTextArea text=new JTextArea(SatuSehatNutritionOrderPayload.JSON.writerWithDefaultPrettyPrinter().writeValueAsString(service.preview(r)),23,80);text.setEditable(false);JOptionPane.showMessageDialog(this,new JScrollPane(text),"Contoh offline: ID pasien/praktisi masih pengganti; bukan payload untuk dikirim",JOptionPane.INFORMATION_MESSAGE);}catch(Exception e){showError(e);}}
    private void send(boolean updating){SatuSehatNutritionOrderService.Row r=selected();if(r==null)return;
        if(JOptionPane.showConfirmDialog(this,(updating?"Update":"Kirim")+" instruksi diet yang dipilih ke endpoint SATUSEHAT pada konfigurasi?\nPastikan petugas gizi telah meninjau data dan dokter pemberi instruksi.","Konfirmasi pengiriman",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;
        work(()->service.send(r,updating),message->{refresh();info.setText(message);});
    }
    private void recover(){SatuSehatNutritionOrderService.Row r=selected();if(r==null)return;String id=JOptionPane.showInputDialog(this,"ID NutritionOrder dari hasil kirim yang berhasil di monitoring SATUSEHAT.\nHanya pemeriksaan GET dan penautan ID; tidak mengirim POST ulang.");if(id!=null)work(()->service.reconcile(r,id.trim()),message->{refresh();info.setText(message);});}
    private void busy(boolean active){search.setEnabled(!active&&SatuSehatNutritionOrderService.canRead());edit.setEnabled(!active&&SatuSehatNutritionOrderService.canEdit());preview.setEnabled(!active&&SatuSehatNutritionOrderService.canRead());for(JButton b:new JButton[]{send,update,recover})b.setEnabled(!active&&SatuSehatNutritionOrderService.canSend());table.setEnabled(!active);from.setEnabled(!active);to.setEnabled(!active);filter.setEnabled(!active);close.setEnabled(!active);setDefaultCloseOperation(active?DO_NOTHING_ON_CLOSE:DISPOSE_ON_CLOSE);}
    private <T> void work(Callable<T> task,Consumer<T> done){busy(true);info.setText("Memproses...");new SwingWorker<T,Void>(){@Override protected T doInBackground()throws Exception{return task.call();}@Override protected void done(){busy(false);try{done.accept(get());}catch(Exception e){showError(e);refresh();}}}.execute();}
    private void showError(Throwable e){String message=SatuSehatNutritionOrderService.errorMessage(e);info.setText(message);JOptionPane.showMessageDialog(this,message,"NutritionOrder",JOptionPane.WARNING_MESSAGE);}
}
